"""The gauge-forward words regenerated by verify.sh must equal the words recorded in checks/generated.json (sha256 of the decompressed
FULL-WORD.json.gz).  usage: wordpins.py EO_ROOT WORKDIR"""
import gzip, hashlib, json, os, sys
root, wk = sys.argv[1], sys.argv[2]
pins = json.load(open(os.path.join(root, 'checks/generated.json')))
bad = 0
for name, want in sorted(pins.items()):
    got = hashlib.sha256(gzip.decompress(open('%s/o_%s/FULL-WORD.json.gz' % (wk, name), 'rb').read())).hexdigest()
    ok = got == want
    bad += not ok
    print(('PASS' if ok else 'FAIL') + ' G0.generated-word-%s  sha256 %s' % (name, got[:16]))
sys.exit(1 if bad else 0)
